input.command:
mkdir -p /output && cat > /output/argparse_layout.mjs <<'EOF'
// Reference reimplementation of CPython 3.12 argparse HelpFormatter layout
// for: parser = ArgumentParser(); parser.add_argument('--a', type=str, required=True)

// --- Python textwrap.wrap, restricted to defaults, no hyphen-breaking needed here ---
export function textwrapWrap(text, width) {
  // replace_whitespace + strip already done by caller
  if (width <= 0) width = 1;
  const words = text.split(' ').filter(w => w.length > 0);
  const lines = [];
  let cur = [];
  let curLen = 0;
  for (let w of words) {
    while (w.length > width) {           // break_long_words=True
      if (curLen > 0) { lines.push(cur.join(' ')); cur = []; curLen = 0; }
      lines.push(w.slice(0, width));
      w = w.slice(width);
    }
    const add = curLen === 0 ? w.length : curLen + 1 + w.length;
    if (curLen > 0 && add > width) {
      lines.push(cur.join(' '));
      cur = [w]; curLen = w.length;
    } else {
      cur.push(w); curLen = add;
    }
  }
  if (cur.length) lines.push(cur.join(' '));
  return lines;
}

const sp = n => ' '.repeat(Math.max(0, n));
const ljust = (s, n) => s + sp(n - s.length);

export function formatHelp({ prog, columnsEnv, isTty = false, ttyColumns = 80 }) {
  // shutil.get_terminal_size(): COLUMNS wins when it parses as int > 0
  let cols = 0;
  if (columnsEnv !== undefined && columnsEnv !== null) {
    const t = String(columnsEnv).trim();
    if (/^[+-]?\d+$/.test(t)) cols = parseInt(t, 10);
  }
  if (cols <= 0) cols = isTty ? ttyColumns : 80;   // fallback (80, 24)
  const width = cols - 2;

  const INDENT_INCREMENT = 2;
  const maxHelpPosition = Math.min(24, Math.max(width - 20, INDENT_INCREMENT * 2));

  const actions = [
    { header: '-h, --help', help: 'show this help message and exit', usage: '[-h]' },
    { header: '--a A',      help: null,                             usage: '--a A' },
  ];

  // ---------------- usage ----------------
  const prefix = 'usage: ';
  const optUsage = actions.map(a => a.usage).join(' ');   // "[-h] --a A"
  const posUsage = '';
  let usage = [prog, optUsage].filter(Boolean).join(' ');
  const textWidth = width - 0; // current_indent == 0

  if (prefix.length + usage.length > textWidth) {
    const partRe = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;
    const optParts = optUsage.match(partRe) || [];        // ['[-h]','--a','A']
    const posParts = posUsage.match(partRe) || [];

    const getLines = (parts, indent, pfx) => {
      const lines = [];
      let line = [];
      let lineLen = (pfx !== undefined ? pfx.length : indent.length) - 1;
      for (const part of parts) {
        if (lineLen + 1 + part.length > textWidth && line.length) {
          lines.push(indent + line.join(' '));
          line = []; lineLen = indent.length - 1;
        }
        line.push(part);
        lineLen += 1 + part.length;
      }
      if (line.length) lines.push(indent + line.join(' '));
      if (pfx !== undefined) lines[0] = lines[0].slice(indent.length);
      return lines;
    };

    let lines;
    if (prefix.length + prog.length <= 0.75 * textWidth) {
      const indent = sp(prefix.length + prog.length + 1);
      if (optParts.length) {
        lines = getLines([prog, ...optParts], indent, prefix);
        lines.push(...getLines(posParts, indent));
      } else if (posParts.length) {
        lines = getLines([prog, ...posParts], indent, prefix);
      } else {
        lines = [prog];
      }
    } else {
      const indent = sp(prefix.length);
      lines = getLines([...optParts, ...posParts], indent);
      if (lines.length > 1) {
        lines = [...getLines(optParts, indent), ...getLines(posParts, indent)];
      }
      lines = [prog, ...lines];
    }
    usage = lines.join('\n');
  }
  const usageBlock = prefix + usage + '\n\n';

  // ---------------- action entries ----------------
  const actionMaxLength = Math.max(...actions.map(a => a.header.length + INDENT_INCREMENT));
  const helpPosition = Math.min(actionMaxLength + 2, maxHelpPosition);
  const helpWidth = Math.max(width - helpPosition, 11);
  const currentIndent = INDENT_INCREMENT;
  const actionWidth = helpPosition - currentIndent - 2;

  let items = '';
  for (const a of actions) {
    let header, indentFirst = 0;
    if (!a.help) {
      header = sp(currentIndent) + a.header + '\n';
      items += header;
      continue;
    } else if (a.header.length <= actionWidth) {
      header = sp(currentIndent) + ljust(a.header, actionWidth) + '  ';
      indentFirst = 0;
    } else {
      header = sp(currentIndent) + a.header + '\n';
      indentFirst = helpPosition;
    }
    const parts = [header];
    const helpLines = textwrapWrap(a.help.replace(/[\t\n\x0b\x0c\r ]+/g, ' ').trim(), helpWidth);
    parts.push(sp(indentFirst) + helpLines[0] + '\n');
    for (const l of helpLines.slice(1)) parts.push(sp(helpPosition) + l + '\n');
    items += parts.join('');
  }

  // section: '\n' + heading + items + '\n'; root joins, collapses \n\n\n+, strips
  let out = usageBlock + '\n' + 'options:\n' + items + '\n';
  out = out.replace(/\n\n\n+/g, '\n\n').replace(/^\n+/, '').replace(/\n+$/, '') + '\n';
  return out;
}
EOF
cat > /output/_verify.mjs <<'EOF'
import { formatHelp } from './argparse_layout.mjs';
process.stdout.write(formatHelp({ prog: process.argv[2], columnsEnv: process.env.COLUMNS }));
EOF
echo written
